275		if _, err := m.ImportSegment(Segment{ID: "bound", Frames: []Frame{
276			{Time: 1100, Observations: []Observation{{ID: "K", X: 1, Y: 0}}}, // 世界 (3,2)，距 K(2,2)=1
277		}}); err != nil {
278			t.Fatalf("boundary case rejected: %v", err)
